interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
  errorInfo: any;
}

// Fix: Changed from extending a potentially ambiguous 'Component' to the explicit 'React.Component' to resolve inheritance-related TypeScript errors.
class GlobalErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  static getDerivedStateFromError(error: any): Partial<ErrorBoundaryState> {
    return { hasError: true, error: error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("CRITICAL: Component Tree Error Caught", error, errorInfo);
    this.setState({ errorInfo });
  }

  handleReset = () => {
    try {
      localStorage.clear();
      window.location.reload();
    } catch (e) {
      window.location.href = window.location.origin;
    }
  };

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100vh',
          backgroundColor: '#052e16',
          color: 'white',
          fontFamily: 'system-ui, sans-serif',
          padding: '2rem',
          textAlign: 'center'
        }}>
          <div style={{ background: '#14532d', padding: '2rem', borderRadius: '1rem', border: '1px solid #155c30', maxWidth: '800px', width: '100%' }}>
            <h1 style={{ color: '#4ade80', fontSize: '1.8rem', marginBottom: '1rem' }}>Application Encountered an Error</h1>
            <p style={{ color: '#86efac', marginBottom: '1.5rem' }}>This usually happens if saved data becomes incompatible. Resetting the app usually fixes it.</p>

            <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
              <pre style={{
                backgroundColor: 'rgba(0,0,0,0.4)',
                padding: '1rem',
                borderRadius: '0.5rem',
                overflow: 'auto',
                fontSize: '0.75rem',
                fontFamily: 'monospace',
                border: '1px solid #155c30',
                color: '#dcfce7',
                maxHeight: '300px'
              }}>
                {this.state.error?.toString()}
                {this.state.errorInfo?.componentStack}
              </pre>
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button 
                onClick={() => window.location.reload()}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#155c30',
                  color: 'white',
                  border: '1px solid #4ade80',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reload App
              </button>
              <button 
                onClick={this.handleReset}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#16a34a',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reset Data & Clear Cache
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children || null;
  }
}

