           <div className="flex items-center space-x-4">
            <div className="flex-shrink-0">
              <svg className="h-9 w-9" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" aria-hidden="true">
                <path d="M54 60H10a6 6 0 0 1-6-6V10a6 6 0 0 1 6-6h44a6 6 0 0 1 6 6v44a6 6 0 0 1-6 6z" fill="#166534"/>
                <text x="12" y="24" fontFamily="Inter, sans-serif" fontSize="12" fontWeight="bold" fill="#ffffff">
                  EX<tspan fill="#4ade80">A</tspan>M
                </text>
                <rect x="12" y="32" width="40" height="3" rx="1.5" fill="#ffffff"/>
                <rect x="12" y="39" width="40" height="3" rx="1.5" fill="#ffffff"/>
                <rect x="12" y="46" width="40" height="3" rx="1.5" fill="#ffffff"/>
                <rect x="12" y="53" width="30" height="3" rx="1.5" fill="#ffffff"/>
                <g transform="translate(26 4) rotate(25)">
                  <path d="M35 15 L35 55 L25 55 L25 15 Z" fill="#16a34a" stroke="#ffffff" strokeWidth="2.5" strokeLinejoin="round" />
                  <path d="M25 55 L30 63 L35 55 Z" fill="#15803d" stroke="#ffffff" strokeWidth="2.5" strokeLinejoin="round" />
                  <path d="M27.5 57 L30 61 L32.5 57 Z" fill="#86efac"/>
                  <rect x="27" y="10" width="6" height="5" rx="3" fill="#15803d" stroke="#ffffff" strokeWidth="2.5" />
                </g>
              </svg>
            </div>
            <div>
              <h1 className="text-lg sm:text-2xl font-bold tracking-tight text-slate-100">
                Sub v2 - Exameno CBE Content Generator
              </h1>
            </div>
          </div>
          <div className="flex items-center gap-x-4">
            {isInstallable && (
                <button
                    onClick={handleInstallClick}
                    className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-emerald-600/20 hover:bg-emerald-600/40 text-emerald-400 border border-emerald-500/50 rounded-lg transition-colors text-sm font-medium"
                    title="Install App"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                    <span>Install App</span>
                </button>
            )}
            {currentUser && (
                <>
                    <div className="text-right hidden sm:block">
                        <p className="text-sm font-medium text-slate-100">{currentUser.name}</p>
                        <p className="text-xs text-slate-400">Guest Access</p>
