        const newBalance = prevUser.credits + amount;
        const newLog: CreditLog = {
            id: `log_${Date.now()}`,
            date: new Date().toISOString(),
            action: action,
            creditsUsed: amount,
            balance: newBalance,
        };
        const updatedUser = {
            ...prevUser,
            credits: newBalance,
            creditLogs: [...(prevUser.creditLogs || []), newLog],
        };
        return updatedUser;
    });
