  };

  const handleDeleteFromLibrary = (id: string) => {
      setLibrary(prev => prev.filter(item => item.id !== id));
      if (content?.id === id) setIsSaved(false);
  };

  const handleGenerateSingleImage = async (questionIndex: number) => {
      if (!content || !content.questions) return;
      const question = content.questions[questionIndex];
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], isGeneratingImage: true };
          return { ...prev, questions: newQuestions };
      });
      try {
          const { imageUrl, imageDescription } = await generateSingleImageForQuestion(
              question,
              { grade: content.metadata?.grade || '', subject: content.metadata?.subject || '' },
              content.metadata?.imageSize || '1K'
          );
          const updatedContent = {
              ...content,
              questions: (content.questions || []).map((q, i) => 
                  i === questionIndex 
                      ? { ...q, imageUrl, imageDescription: imageDescription || q.imageDescription, isGeneratingImage: false }
                      : q
              )
          };
          setContent(updatedContent);
          setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
      } catch (e) {
          setContent(prev => {
              if (!prev || !prev.questions) return prev;
              const newQuestions = [...prev.questions];
              newQuestions[questionIndex] = { ...newQuestions[questionIndex], isGeneratingImage: false };
              return { ...prev, questions: newQuestions };
          });
      }
  };

  const handleDeleteQuestionImage = (questionIndex: number) => {
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], imageUrl: undefined, imageDescription: undefined };
          return { ...prev, questions: newQuestions };
      });
  };

  const handleUploadQuestionImage = (questionIndex: number, imageBase64: string) => {
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], imageUrl: imageBase64 };
          return { ...prev, questions: newQuestions };
      });
  };

  const handleApplySuggestion = async (suggestionType: any) => {
      if (!content) return;
      setIsSuggestionLoading(suggestionType);
      try {
          const updatedContentParts = await applyAISuggestion(content, suggestionType);
          const newContent = { ...content, ...updatedContentParts };
          setContent(newContent);
          setLibrary(prev => prev.map(item => item.id === newContent.id ? newContent : item));
      } catch (e) {
          alert("Failed to apply suggestion.");
      } finally {
          setIsSuggestionLoading(null);
      }
  };

  const handleDeleteQuestion = (index: number) => {
      if(!content || !content.questions) return;
      const newQuestions = [...content.questions];
      newQuestions.splice(index, 1);
      const updatedContent = {...content, questions: newQuestions};
      setContent(updatedContent);
      setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
  };

  const handleUpdateQuestion = (index: number, updatedQuestion: GeneratedQuestion) => {
      if(!content || !content.questions) return;
      const newQuestions = [...content.questions];
      newQuestions[index] = updatedQuestion;
      const updatedContent = {...content, questions: newQuestions};
      setContent(updatedContent);
      setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
  };

  const handleContentUpdate = (updatedContent: GeneratedContent) => {
      setContent(updatedContent);
      if (library.some(i => i.id === updatedContent.id)) {
          setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
      }
  };

  const tabs = [
    { id: 'home', label: 'Generator', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg> },
    { id: 'subscription', label: 'Subscription Credit', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" /></svg> },
    { id: 'help', label: 'Help', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> },
    { id: 'feedback', label: 'Feedback', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg> }
  ];

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors duration-300 flex flex-col">
      <Header grade={formState.grade} subject={formState.subject} currentUser={currentUser} />

      <div className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 shadow-sm sticky top-[72px] z-10 print:hidden">
         <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex space-x-1 overflow-x-auto no-scrollbar py-2">
                {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg whitespace-nowrap transition-all duration-200 ${activeTab === tab.id ? 'bg-emerald-600 text-white shadow-md' : 'text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-800'}`}>
                        {tab.icon} {tab.label}
                    </button>
                ))}
            </div>
         </div>
      </div>

      <main className="flex-grow max-w-7xl mx-auto w-full py-6 px-4 sm:px-6 lg:px-8">
        {activeTab === 'home' && (
             <div className="flex flex-col lg:flex-row gap-8">
                <div className="lg:w-1/3 lg:min-w-[350px]">
                    <div className="sticky top-32">
                        <GeneratorForm formState={formState} setFormState={setFormState} onSubmit={handleGenerateContent} isLoading={isLoading} onStartNew={() => { setFormState(initialFormState); setContent(null); }} />
                        {error && (
                        <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/30 border-l-4 border-red-500 text-red-700 dark:text-red-200 rounded shadow-sm">
                            <div className="flex"><div className="ml-3"><p className="font-bold text-sm">Error</p><p className="text-sm mt-1">{error}</p></div></div>
                        </div>
                        )}
                    </div>
                </div>
                <div className="lg:w-2/3">
                    <ContentDisplay content={content} onContentUpdate={handleContentUpdate} exportHeaderInfo={exportHeaderInfo} setExportHeaderInfo={setExportHeaderInfo} assessmentExportType={assessmentExportType} setAssessmentExportType={setAssessmentExportType} onContentBodyUpdate={(newBody) => setContent(prev => prev ? ({...prev, body: newBody}) : null)} onUpdateQuestion={handleUpdateQuestion} onDeleteQuestion={handleDeleteQuestion} onGenerateSingleImage={handleGenerateSingleImage} onDeleteQuestionImage={handleDeleteQuestionImage} onUploadQuestionImage={handleUploadQuestionImage} onApplySuggestion={handleApplySuggestion} onSaveToLibrary={handleSaveToLibrary} isSaved={isSaved} isSuggestionLoading={isSuggestionLoading} />
                </div>
            </div>
        )}
        {activeTab === 'library' && <TeacherDashboard currentUser={currentUser} library={library} onSelectContent={handleSelectFromLibrary} onDeleteContent={handleDeleteFromLibrary} onBuyCredits={() => setActiveTab('subscription')} />}
        {activeTab === 'help' && <HelpGuide />}
        {activeTab === 'feedback' && <FeedbackPanel currentUser={currentUser} />}
        {activeTab === 'subscription' && <SubscriptionPanel currentUser={currentUser} onUpdateCredits={handleUpdateCredits} />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GeneratedContent, QuestionType, ExportHeaderInfo, AssessmentExportType, GeneratedQuestion, SchemeOfWorkData, ROWCFormData, SchemeOfWorkEntry, ROWCLessonEntry } from '../types.ts';
import { ExportControls } from './ExportControls.tsx';
import { AISuggestions } from './AISuggestions.tsx';
import MarkdownRenderer from '../utils/MarkdownRenderer.tsx';
import { summarizeContent, generateRubric, regenerateQuestion } from '../services/geminiService.ts';

interface ContentDisplayProps {
  content: GeneratedContent | null;
  onContentUpdate?: (updatedContent: GeneratedContent) => void;
  onContentBodyUpdate?: (newBody: string) => void;
  onDeleteQuestionImage?: (questionIndex: number) => void;
  onUploadQuestionImage?: (questionIndex: number, imageBase64: string) => void;
  onApplySuggestion?: (suggestionType: 'BLOOMS_TAXONOMY' | 'LEARNING_OUTCOMES' | 'GRADING_RUBRIC' | 'IMPROVE_QUESTIONS' | 'GENERATE_LESSON_PLAN') => void;
  onGenerateSingleImage?: (questionIndex: number) => void;
  onDeleteQuestion?: (questionIndex: number) => void;
  onUpdateQuestion?: (questionIndex: number, updatedQuestion: GeneratedQuestion) => void;
  exportHeaderInfo: ExportHeaderInfo;
  setExportHeaderInfo: React.Dispatch<React.SetStateAction<ExportHeaderInfo>>;
  assessmentExportType: AssessmentExportType;
  setAssessmentExportType: React.Dispatch<React.SetStateAction<AssessmentExportType>>;
  isSuggestionLoading?: string | null;
  isReadOnly?: boolean; 
  onSaveToLibrary?: () => void;
  isSaved?: boolean;
  showAutoSaveToast?: boolean;
}

const formatSowOutcomes = (text: string) => {
    if (!text) return '';
    return text.replace(/(Knowledge:|Skills:|Attitudes:)/g, '**$1**');
};

const EditableTextarea: React.FC<{ value: string; onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void; onBlur: () => void }> = ({ value, onChange, onBlur }) => {
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
            textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
            textareaRef.current.focus();
            textareaRef.current.select();
        }
    }, [value]);

    return (
        <textarea
            ref={textareaRef}
            value={value}
            onChange={onChange}
            onBlur={onBlur}
            onKeyDown={(e) => { if (e.key === 'Escape') { (e.target as HTMLTextAreaElement).blur(); } }}
            className="w-full bg-slate-100 dark:bg-slate-700 p-2 rounded border border-emerald-500 focus:outline-none text-sm text-slate-900 dark:text-white min-h-[50px] resize-y"
        />
    );
};

export const ContentDisplay: React.FC<ContentDisplayProps> = ({ 
  content, 
  onContentUpdate,
  onContentBodyUpdate, 
  onDeleteQuestionImage, 
  onUploadQuestionImage, 
  onGenerateSingleImage, 
  onDeleteQuestion, 
  onUpdateQuestion, 
  exportHeaderInfo, 
  setExportHeaderInfo, 
  assessmentExportType, 
  setAssessmentExportType, 
  onApplySuggestion, 
  isSuggestionLoading, 
  isReadOnly = false, 
  onSaveToLibrary, 
  isSaved,
  showAutoSaveToast
}) => {
  const [editingQuestionIndex, setEditingQuestionIndex] = useState<number | null>(null);
  const [editedQuestion, setEditedQuestion] = useState<GeneratedQuestion | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [showSaveFeedback, setShowSaveFeedback] = useState(false);
  const [openQuestionMenuIndex, setOpenQuestionMenuIndex] = useState<number | null>(null);

  const [isSummarizing, setIsSummarizing] = useState(false);
  const [localSuggestionLoading, setLocalSuggestionLoading] = useState<string | null>(null);
  const [isRegeneratingQuestion, setIsRegeneratingQuestion] = useState<number | null>(null);

  const [regeneratingSectionIndex, setRegeneratingSectionIndex] = useState<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isEditingBody, setIsEditingBody] = useState(false);
  const [editedBody, setEditedBody] = useState('');

  const [editingCell, setEditingCell] = useState<{ type: 'rowc' | 'sow'; id: string; field: string } | null>(null);
  const [editText, setEditText] = useState('');

  useEffect(() => {
    setCurrentPage(1);
    setEditingQuestionIndex(null);
    setLocalSuggestionLoading(null);
    setRegeneratingSectionIndex(null);
    setOpenQuestionMenuIndex(null);
    setIsEditingBody(false);
    setEditingCell(null);
  }, [content?.id]);

  const handleStartEditingCell = (type: 'rowc' | 'sow', id: string, field: string, currentText: string) => {
    if (editingCell) handleSaveCell(); // Save previous cell if one was being edited
    setEditingCell({ type, id, field });
    setEditText(currentText);
  };

  const handleSaveCell = () => {
    if (!editingCell || !content || !onContentUpdate) {
        setEditingCell(null);
        return;
    }

    let updatedContent = { ...content };

    if (editingCell.type === 'rowc' && updatedContent.rowcData) {
        updatedContent.rowcData = {
            ...updatedContent.rowcData,
            lessons: updatedContent.rowcData.lessons.map(lesson => 
                lesson.id === editingCell.id ? { ...lesson, [editingCell.field as keyof ROWCLessonEntry]: editText } : lesson
            )
        };
    } else if (editingCell.type === 'sow' && updatedContent.schemeOfWorkData) {
        const entryIndex = parseInt(editingCell.id, 10);
        updatedContent.schemeOfWorkData = {
            ...updatedContent.schemeOfWorkData,
            entries: updatedContent.schemeOfWorkData.entries.map((entry, index) => 
                index === entryIndex ? { ...entry, [editingCell.field as keyof SchemeOfWorkEntry]: editText } : entry
            )
        };
    }

    onContentUpdate(updatedContent);
    setEditingCell(null);
  };

  const handleSummarize = async () => {
    if (!content || !onContentUpdate) return;
    setIsSummarizing(true);
    try {
      const sum = await summarizeContent(content);
      onContentUpdate({ ...content, summary: sum });
    } catch (e) {
      alert('Summarization failed.');
    } finally {
      setIsSummarizing(false);
    }
  };

  const handleStartEditingQuestion = (index: number) => {
    setEditingQuestionIndex(index);
    setEditedQuestion(JSON.parse(JSON.stringify(content!.questions![index])));
    setOpenQuestionMenuIndex(null);
  };

  const handleSaveEditingQuestion = () => {
    if (onUpdateQuestion && editingQuestionIndex !== null && editedQuestion) {
      onUpdateQuestion(editingQuestionIndex, editedQuestion);
    }
    setEditingQuestionIndex(null);
    setEditedQuestion(null);
  };

  const handleRegenerateQuestion = async (index: number) => {
    if (!content || !content.questions || !onUpdateQuestion) return;
    setIsRegeneratingQuestion(index);
    setOpenQuestionMenuIndex(null);
    try {
      const context = content.body || JSON.stringify(content.questions.map(q => q.questionText));
      const newQ = await regenerateQuestion(content.questions[index], context);
      onUpdateQuestion(index, newQ);
    } catch (e) {
      alert('Regeneration failed.');
    } finally {
      setIsRegeneratingQuestion(null);
    }
  };

  const handleApplySuggestionInternal = async (suggestionType: any) => {
      if (suggestionType === 'GRADING_RUBRIC') {
          setLocalSuggestionLoading('GRADING_RUBRIC');
          try {
              const rubric = await generateRubric(content!);
              if (onContentUpdate) {
                onContentUpdate({ ...content!, rubric: rubric });
              }
          } catch (e) {
              alert('Failed to generate rubric.');
          } finally {
              setLocalSuggestionLoading(null);
          }
      } else if (onApplySuggestion) {
          onApplySuggestion(suggestionType);
      }
  };

  const handleImageUploadTrigger = (index: number) => {
    setOpenQuestionMenuIndex(null);
    if (fileInputRef.current) {
      fileInputRef.current.setAttribute('data-target-index', index.toString());
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const indexStr = e.target.getAttribute('data-target-index');
    if (file && indexStr && onUploadQuestionImage) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        onUploadQuestionImage(parseInt(indexStr), base64);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  if (!content) {
    return (
      <div className="bg-white/50 dark:bg-slate-800/50 border border-gray-300 dark:border-slate-700 border-dashed p-12 rounded-2xl shadow-sm text-center text-gray-500 dark:text-slate-400 flex flex-col justify-center items-center h-full min-h-[400px]">
        <div className="bg-slate-100 dark:bg-slate-700/50 p-4 rounded-full mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m2.25 0H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" /></svg>
        </div>
        <p className="text-lg font-semibold text-gray-700 dark:text-slate-200">Your generated content will appear here.</p>
      </div>
    );
  }

  const QUESTIONS_PER_PAGE = 10;
  const isPaginated = content.questions && content.questions.length > QUESTIONS_PER_PAGE;
  const totalPages = isPaginated ? Math.ceil(content.questions!.length / QUESTIONS_PER_PAGE) : 1;
  const startIndex = (currentPage - 1) * QUESTIONS_PER_PAGE;
  const currentQuestions = isPaginated ? content.questions!.slice(startIndex, startIndex + QUESTIONS_PER_PAGE) : (content.questions || []);

  const SchemeOfWorkTable: React.FC<{ data: SchemeOfWorkData }> = ({ data }) => (
    <div className="overflow-x-auto my-8 border border-slate-200 dark:border-slate-700 rounded-xl shadow-lg">
        <table className="min-w-full divide-y divide-slate-200 dark:divide-slate-700 text-sm">
            <thead className="bg-slate-50 dark:bg-slate-800">
                <tr>
                    {['Wk', 'Lsn', 'Strand', 'Sub-Strand', 'Learning Outcomes', 'Key Inquiry Questions', 'Learning Experiences', 'Learning Resources', 'Assessment', 'Remarks'].map(header => (
                        <th key={header} className="px-3 py-4 text-left font-bold text-slate-900 dark:text-white uppercase tracking-wider">{header}</th>
                    ))}
                </tr>
            </thead>
            <tbody className="bg-white dark:bg-slate-900 divide-y divide-slate-200 dark:divide-slate-800">
                {data.entries.map((entry, i) => (
                    <tr key={entry.id || i} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                        {(Object.keys(entry) as Array<keyof SchemeOfWorkEntry>).filter(key => key !== 'id').map(key => (
                            <td key={key} className="px-3 py-4 text-slate-900 dark:text-white" onClick={() => handleStartEditingCell('sow', `${i}`, key, entry[key])}>
                                {editingCell?.type === 'sow' && editingCell.id === `${i}` && editingCell.field === key ? (
                                    <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} />
                                ) : (
                                    <MarkdownRenderer markdown={key === 'learningOutcomes' ? formatSowOutcomes(entry[key]) : entry[key]} className="prose-xs" />
                                )}
                            </td>
                        ))}
                    </tr>
                ))}
            </tbody>
        </table>
    </div>
);

const ROWCTable: React.FC<{ data: ROWCFormData }> = ({ data }) => (
    <div className="overflow-x-auto my-8 border border-slate-200 dark:border-slate-700 rounded-xl shadow-lg">
        <table className="min-w-full divide-y divide-slate-200 dark:divide-slate-700 text-sm">
            <thead className="bg-slate-50 dark:bg-slate-800">
                <tr>
                    {['Date', 'Strand/Lesson', 'Activities', 'Resources', 'Remarks'].map(header => (
                         <th key={header} className="px-3 py-4 text-left font-bold text-slate-900 dark:text-white uppercase tracking-wider">{header}</th>
                    ))}
                </tr>
            </thead>
            <tbody className="bg-white dark:bg-slate-900 divide-y divide-slate-200 dark:divide-slate-800">
                {data.lessons.map((lesson) => (
                    <tr key={lesson.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="px-3 py-4 whitespace-nowrap text-slate-900 dark:text-white font-medium" onClick={() => handleStartEditingCell('rowc', lesson.id, 'date', lesson.date)}>
                            {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'date' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : lesson.date}
                        </td>
                        <td className="px-3 py-4">
                            <div className="font-bold text-emerald-700 dark:text-white" onClick={() => handleStartEditingCell('rowc', lesson.id, 'strand', lesson.strand)}>
                                {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'strand' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : lesson.strand}
                            </div>
                            <div className="text-xs text-slate-500 dark:text-white" onClick={() => handleStartEditingCell('rowc', lesson.id, 'lessonTitle', lesson.lessonTitle)}>
                                {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'lessonTitle' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : lesson.lessonTitle}
                            </div>
                        </td>
                        <td className="px-3 py-4 text-slate-700 dark:text-white" onClick={() => handleStartEditingCell('rowc', lesson.id, 'learningActivities', lesson.learningActivities)}>
                             {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'learningActivities' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : <MarkdownRenderer markdown={lesson.learningActivities} className="prose-xs" />}
                        </td>
                        <td className="px-3 py-4 text-slate-700 dark:text-white" onClick={() => handleStartEditingCell('rowc', lesson.id, 'resources', lesson.resources)}>
                             {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'resources' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : lesson.resources}
                        </td>
                        <td className="px-3 py-4 text-slate-600 dark:text-white italic" onClick={() => handleStartEditingCell('rowc', lesson.id, 'remarks', lesson.remarks)}>
                             {editingCell?.type === 'rowc' && editingCell.id === lesson.id && editingCell.field === 'remarks' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : <MarkdownRenderer markdown={lesson.remarks} className="prose-xs" />}
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
        {data.reflection && (
            <div className="p-4 bg-slate-50 dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700" onClick={() => handleStartEditingCell('rowc', 'main', 'reflection', data.reflection)}>
                <h4 className="text-xs font-bold uppercase tracking-widest text-slate-500 mb-1">Teacher's Reflection</h4>
                {editingCell?.type === 'rowc' && editingCell.id === 'main' && editingCell.field === 'reflection' ? <EditableTextarea value={editText} onChange={e => setEditText(e.target.value)} onBlur={handleSaveCell} /> : <p className="text-sm text-slate-700 dark:text-slate-300 italic">{data.reflection}</p>}
            </div>
        )}
    </div>
);


  return (
