import React, { ErrorInfo, ReactNode, Component } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import { MemoryRouter } from 'react-router-dom';
import { ThemeProvider } from './hooks/useTheme';

console.log("🏫 Initializing Exameno ECG Application...");

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
  errorInfo: any;
}

// Fix: Destructured `Component` from the React import and extended it directly. This resolves an obscure TypeScript type resolution issue where `React.Component` was not being correctly identified, leading to errors where instance properties like `props` and `setState` were not found.
class GlobalErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  // Fix: Replaced constructor-based state initialization with a class property. This modern syntax resolves TypeScript errors where `this.state`, `this.props`, and `this.setState` were not found on the component instance.
  state: ErrorBoundaryState = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  static getDerivedStateFromError(error: any): Partial<ErrorBoundaryState> {
    return { hasError: true, error: error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("CRITICAL: Component Tree Error Caught", error, errorInfo);
    this.setState({ errorInfo });
  }

  handleReset = () => {
    try {
      localStorage.clear();
      window.location.reload();
    } catch (e) {
      window.location.href = window.location.origin;
    }
  };

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100vh',
          backgroundColor: '#011a15',
          color: 'white',
          fontFamily: 'system-ui, sans-serif',
          padding: '2rem',
          textAlign: 'center'
        }}>
          <div style={{ background: '#022c22', padding: '2rem', borderRadius: '1rem', border: '1px solid #064e3b', maxWidth: '800px', width: '100%' }}>
            <h1 style={{ color: '#34d399', fontSize: '1.8rem', marginBottom: '1rem' }}>Application Encountered an Error</h1>
            <p style={{ color: '#6ee7b7', marginBottom: '1.5rem' }}>This usually happens if saved data becomes incompatible. Resetting the app usually fixes it.</p>

            <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
              <pre style={{
                backgroundColor: 'rgba(0,0,0,0.4)',
                padding: '1rem',
                borderRadius: '0.5rem',
                overflow: 'auto',
                fontSize: '0.75rem',
                fontFamily: 'monospace',
                border: '1px solid #064e3b',
                color: '#d1fae5',
                maxHeight: '300px'
              }}>
                {this.state.error?.toString()}
                {this.state.errorInfo?.componentStack}
              </pre>
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button 
                onClick={() => window.location.reload()}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#064e3b',
                  color: 'white',
                  border: '1px solid #34d399',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reload App
              </button>
              <button 
                onClick={this.handleReset}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#059669',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reset Data & Clear Cache
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children || null;
  }
}

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(
    <GlobalErrorBoundary>
      <MemoryRouter>
        <ThemeProvider>
          <App />
        </ThemeProvider>
      </MemoryRouter>
    </GlobalErrorBoundary>
  );
} else {
    console.error("Root element not found");
}

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import { GeneratorForm } from './components/GeneratorForm';
import { ContentDisplay } from './components/ContentDisplay';
import { FormState, GeneratedContent, ContentType, QuestionDifficulty, ExportHeaderInfo, AssessmentExportType, GeneratedQuestion, QuestionType, User, CreditLog } from './types';
import { generateContent, generateSingleImageForQuestion, applyAISuggestion } from './services/geminiService';
import TeacherDashboard from './components/TeacherDashboard';
import AdminPanel from './components/AdminPanel';
import HelpGuide from './components/HelpGuide';
import FeedbackPanel from './components/FeedbackPanel';
import SubscriptionPanel from './components/SubscriptionPanel.tsx';
import { stripImageData } from './utils/storageUtils';

const APP_VERSION = '1.0.5';

// Mock a static guest user for components that still expect a user object
const GUEST_USER: User = {
    id: 1,
    name: 'Teacher',
    email: 'guest@exameno.com',
    role: 'Teacher',
    status: 'Active',
    avatarColor: 'bg-emerald-600',
    credits: 999,
    schoolName: 'Exameno School'
};

const initialFormState: FormState = {
  grade: 'Grade 3',
  subject: 'CRE',
  topic: '',
  contentType: ContentType.SchemeOfWork,
  difficulty: QuestionDifficulty.Mixed,
  topicInputMode: 'curriculum',
  multiSelectTopics: {},
  terms: [],
  distributionMode: 'manual',
  totalQuestions: 25,
  questionCounts: {
      [QuestionType.MultipleChoice]: 20,
      [QuestionType.ShortAnswer]: 5
  },
  questionMarks: {
      [QuestionType.MultipleChoice]: 1,
      [QuestionType.ShortAnswer]: 2,
      [QuestionType.TrueFalse]: 1,
      [QuestionType.Essay]: 10,
      [QuestionType.Discussion]: 5
  },
  additionalInstructions: '',
  generateImages: false,
  imageSize: '1K',
  textbookReference: '',
  strictCurriculumAdherence: true,
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'library' | 'subscription' | 'help' | 'feedback' | 'admin'>('home');
  const [isSaved, setIsSaved] = useState(false);
  const [content, setContent] = useState<GeneratedContent | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formState, setFormState] = useState<FormState>(() => {
    try {
      const savedState = localStorage.getItem('examenoFormState');
      if (!savedState) return initialFormState;
      const parsed = JSON.parse(savedState);
      return { ...initialFormState, ...parsed };
    } catch (e) { return initialFormState; }
  });

  const [currentUser, setCurrentUser] = useState<User>(GUEST_USER);

  const [library, setLibrary] = useState<GeneratedContent[]>(() => {
      try {
          const saved = localStorage.getItem('examenoLibrary');
          if (!saved) return [];
          const parsed = JSON.parse(saved);
          return Array.isArray(parsed) ? parsed : [];
      } catch { return []; }
  });

  const [exportHeaderInfo, setExportHeaderInfo] = useState<ExportHeaderInfo>({
    includeHeader: false,
    schoolName: 'Exameno School',
    teacherName: 'Teacher',
    gradeLevel: '',
    subject: '',
    contentType: '',
    term: '',
    fontFamily: 'Arial',
    layoutColumns: 'one',
    spacing: 'normal',
    tableStyle: 'lightHorizontalLines',
    pageMargins: 'normal',
    includeAudit: false,
    includeRubric: false,
  });

  const [assessmentExportType, setAssessmentExportType] = useState<AssessmentExportType>(AssessmentExportType.QuestionsAndAnswers);
  const [isSuggestionLoading, setIsSuggestionLoading] = useState<string | null>(null);

  useEffect(() => {
    try {
      localStorage.setItem('examenoFormState', JSON.stringify(formState));
    } catch (e) {}
  }, [formState]);

  useEffect(() => {
    const libraryToSave = library.map(stripImageData);
    try {
        localStorage.setItem('examenoLibrary', JSON.stringify(libraryToSave));
    } catch (e) {
        console.error("Library storage potentially full", e);
    }
  }, [library]);

  const handleGenerateContent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setContent(null);
    setIsSaved(false);
    try {
      const result = await generateContent(formState, 'Teacher', 'Exameno School');
      const contentWithTimestamp = { ...result, savedAt: new Date().toISOString() };
      setContent(contentWithTimestamp);
      setLibrary(prev => [contentWithTimestamp, ...prev]);
      setIsSaved(true);

      setExportHeaderInfo(prev => ({
          ...prev,
          gradeLevel: result.metadata?.grade || '',
          subject: result.metadata?.subject || '',
          contentType: result.metadata?.contentType || '',
          term: result.metadata?.term || formState.terms?.[0] || ''
      }));
    } catch (err: any) {
      setError(err.message || "Generation failed.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateCredits = (amount: number, action: string) => {
    setCurrentUser(prevUser => {
        if (!prevUser) return prevUser;
        const newBalance = prevUser.credits + amount;
        const newLog: CreditLog = {
            id: `log_${Date.now()}`,
            date: new Date().toISOString(),
            action: action,
            creditsUsed: amount,
            balance: newBalance,
        };
        const updatedUser = {
            ...prevUser,
            credits: newBalance,
            creditLogs: [...(prevUser.creditLogs || []), newLog],
        };
        return updatedUser;
    });
  };

  const handleSaveToLibrary = () => {
      if (!content) return;
      if (library.find(item => item.id === content.id)) return;
      const contentToSave = { ...content, savedAt: new Date().toISOString() };
      setLibrary(prev => [contentToSave, ...prev]);
      setIsSaved(true);
  };

  const handleSelectFromLibrary = (selectedContent: GeneratedContent) => {
      setContent(selectedContent);
      setActiveTab('home');
      setFormState(prev => ({
          ...prev,
          grade: selectedContent.metadata?.grade || prev.grade,
          subject: selectedContent.metadata?.subject || prev.subject,
          contentType: selectedContent.metadata?.contentType || prev.contentType,
          topic: selectedContent.metadata?.topic || prev.topic
      }));
  };

  const handleDeleteFromLibrary = (id: string) => {
      setLibrary(prev => prev.filter(item => item.id !== id));
      if (content?.id === id) setIsSaved(false);
  };

  const handleGenerateSingleImage = async (questionIndex: number) => {
      if (!content || !content.questions) return;
      const question = content.questions[questionIndex];
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], isGeneratingImage: true };
          return { ...prev, questions: newQuestions };
      });
      try {
          const { imageUrl, imageDescription } = await generateSingleImageForQuestion(
              question,
              { grade: content.metadata?.grade || '', subject: content.metadata?.subject || '' },
              content.metadata?.imageSize || '1K'
          );
          const updatedContent = {
              ...content,
              questions: (content.questions || []).map((q, i) => 
                  i === questionIndex 
                      ? { ...q, imageUrl, imageDescription: imageDescription || q.imageDescription, isGeneratingImage: false }
                      : q
              )
          };
          setContent(updatedContent);
          setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
      } catch (e) {
          setContent(prev => {
              if (!prev || !prev.questions) return prev;
              const newQuestions = [...prev.questions];
              newQuestions[questionIndex] = { ...newQuestions[questionIndex], isGeneratingImage: false };
              return { ...prev, questions: newQuestions };
          });
      }
  };

  const handleDeleteQuestionImage = (questionIndex: number) => {
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], imageUrl: undefined, imageDescription: undefined };
          return { ...prev, questions: newQuestions };
      });
  };

  const handleUploadQuestionImage = (questionIndex: number, imageBase64: string) => {
      setContent(prev => {
          if (!prev || !prev.questions) return prev;
          const newQuestions = [...prev.questions];
          newQuestions[questionIndex] = { ...newQuestions[questionIndex], imageUrl: imageBase64 };
          return { ...prev, questions: newQuestions };
      });
  };

  const handleApplySuggestion = async (suggestionType: any) => {
      if (!content) return;
      setIsSuggestionLoading(suggestionType);
      try {
          const updatedContentParts = await applyAISuggestion(content, suggestionType);
          const newContent = { ...content, ...updatedContentParts };
          setContent(newContent);
          setLibrary(prev => prev.map(item => item.id === newContent.id ? newContent : item));
      } catch (e) {
          alert("Failed to apply suggestion.");
      } finally {
          setIsSuggestionLoading(null);
      }
  };

  const handleDeleteQuestion = (index: number) => {
      if(!content || !content.questions) return;
      const newQuestions = [...content.questions];
      newQuestions.splice(index, 1);
      const updatedContent = {...content, questions: newQuestions};
      setContent(updatedContent);
      setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
  };

  const handleUpdateQuestion = (index: number, updatedQuestion: GeneratedQuestion) => {
      if(!content || !content.questions) return;
      const newQuestions = [...content.questions];
      newQuestions[index] = updatedQuestion;
      const updatedContent = {...content, questions: newQuestions};
      setContent(updatedContent);
      setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
  };

  const handleContentUpdate = (updatedContent: GeneratedContent) => {
      setContent(updatedContent);
      if (library.some(i => i.id === updatedContent.id)) {
          setLibrary(prev => prev.map(item => item.id === updatedContent.id ? updatedContent : item));
      }
  };

  const tabs = [
    { id: 'home', label: 'Generator', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg> },
    { id: 'subscription', label: 'Subscription Credit', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" /></svg> },
    { id: 'help', label: 'Help', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> },
    { id: 'feedback', label: 'Feedback', icon: <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg> }
  ];

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors duration-300 flex flex-col">
      <Header grade={formState.grade} subject={formState.subject} currentUser={currentUser} />

      <div className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 shadow-sm sticky top-[72px] z-10 print:hidden">
         <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex space-x-1 overflow-x-auto no-scrollbar py-2">
                {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg whitespace-nowrap transition-all duration-200 ${activeTab === tab.id ? 'bg-emerald-600 text-white shadow-md' : 'text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-800'}`}>
                        {tab.icon} {tab.label}
                    </button>
                ))}
            </div>
         </div>
      </div>

      <main className="flex-grow max-w-7xl mx-auto w-full py-6 px-4 sm:px-6 lg:px-8">
        {activeTab === 'home' && (
             <div className="flex flex-col lg:flex-row gap-8">
                <div className="lg:w-1/3 lg:min-w-[350px]">
                    <div className="sticky top-32">
                        <GeneratorForm formState={formState} setFormState={setFormState} onSubmit={handleGenerateContent} isLoading={isLoading} onStartNew={() => { setFormState(initialFormState); setContent(null); }} />
                        {error && (
                        <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/30 border-l-4 border-red-500 text-red-700 dark:text-red-200 rounded shadow-sm">
                            <div className="flex"><div className="ml-3"><p className="font-bold text-sm">Error</p><p className="text-sm mt-1">{error}</p></div></div>
                        </div>
                        )}
                    </div>
                </div>
                <div className="lg:w-2/3">
                    <ContentDisplay content={content} onContentUpdate={handleContentUpdate} exportHeaderInfo={exportHeaderInfo} setExportHeaderInfo={setExportHeaderInfo} assessmentExportType={assessmentExportType} setAssessmentExportType={setAssessmentExportType} onContentBodyUpdate={(newBody) => setContent(prev => prev ? ({...prev, body: newBody}) : null)} onUpdateQuestion={handleUpdateQuestion} onDeleteQuestion={handleDeleteQuestion} onGenerateSingleImage={handleGenerateSingleImage} onDeleteQuestionImage={handleDeleteQuestionImage} onUploadQuestionImage={handleUploadQuestionImage} onApplySuggestion={handleApplySuggestion} onSaveToLibrary={handleSaveToLibrary} isSaved={isSaved} isSuggestionLoading={isSuggestionLoading} />
                </div>
            </div>
        )}
        {activeTab === 'library' && <div>Redirecting...</div>}
        {activeTab === 'help' && <HelpGuide />}
        {activeTab === 'feedback' && <FeedbackPanel currentUser={currentUser} />}
        {activeTab === 'subscription' && <SubscriptionPanel currentUser={currentUser} onUpdateCredits={handleUpdateCredits} />}
      </main>
    </div>
  );
};

export default App;

export enum ContentType {
  LessonPlan = 'Lesson Plan',
