const FAILED_IMAGE_PLACEHOLDER = 'data:image/svg+xml;base64,';

const PRO_MODEL = 'gemini-3-pro-preview';
const FLASH_MODEL = 'gemini-3-flash-preview';
const IMAGE_FLASH = 'gemini-2.5-flash-image';
const IMAGE_PRO = 'gemini-3-pro-image-preview';

const getAI = () => {
    // Guideline: Initialize with new GoogleGenAI({apiKey: process.env.API_KEY}) directly
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const isKiswahili = (subject: string) => subject && subject.toLowerCase().includes('kiswahili');

export async function generateImage(prompt: string, subject: string, metadata: { grade: string }, isForQuestion: boolean = false, imageSize: '1K' | '2K' | '4K' = '1K', aspectRatio?: string): Promise<string> {
    try {
        const fullPrompt = `An educational illustration for a Kenyan Competency-Based Curriculum (CBC) ${metadata.grade} ${subject} class. The style should be clean, simple, colorful, and culturally relevant to Kenyan learners. 
        CRITICAL: Background MUST be solid, plain white. DO NOT use patterns or gradients.
        ${isForQuestion 
            ? "Pedagogical Note: This image is a visual aid for an assessment. 1. Label parts clearly with letters (A, B, C) if the question refers to them. 2. DO NOT include the names of parts in the image itself to avoid giving away the answer." 
            : ""} 
        Content to illustrate: ${prompt}`;

        const isHighQuality = imageSize === '2K' || imageSize === '4K';
        const modelName = isHighQuality ? IMAGE_PRO : IMAGE_FLASH;

        if (isHighQuality && typeof window !== 'undefined' && (window as any).aistudio) {
             const aistudio = (window as any).aistudio;
             if (!await aistudio.hasSelectedApiKey()) {
                 await aistudio.openSelectKey();
             }
        }

        // Guideline: Create a new GoogleGenAI instance right before making an API call to use the latest API key
        const ai = getAI();
        const response = await ai.models.generateContent({
            model: modelName,
            contents: { parts: [{ text: fullPrompt }] },
            config: {
                imageConfig: {
                    aspectRatio: aspectRatio || "1:1",
                    imageSize: isHighQuality ? imageSize : undefined
                }
            },
        });

        for (const part of response.candidates[0].content.parts) {
            // Find the image part as per nano banana series guidelines
            if (part.inlineData) {
                return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            }
        }
        throw new Error("No image data found.");

    } catch (error: any) {
        console.error("Image generation failed:", error);
        if (error.message?.includes("Requested entity was not found.") && typeof window !== 'undefined' && (window as any).aistudio) {
             (window as any).aistudio.openSelectKey();
        }
        return FAILED_IMAGE_PLACEHOLDER;
    }
}

export async function generateSingleImageForQuestion(
  q: GeneratedQuestion,
  metadata: { grade: string; subject: string },
  imageSize: '1K' | '2K' | '4K' = '1K'
): Promise<{ imageUrl: string; imageDescription: string }> {
  const description = q.imageDescription || q.questionText;
  if (!description) return { imageUrl: '', imageDescription: '' };
  const imageUrl = await generateImage(description, metadata.subject, { grade: metadata.grade }, true, imageSize);
  return { imageUrl, imageDescription: description };
}

