const SystemBackupRestore: React.FC = () => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleBackup = () => {
        const backup = {
            users: JSON.parse(localStorage.getItem('examenoUsers') || '[]'),
            library: JSON.parse(localStorage.getItem('examenoLibrary') || '[]'),
            feedback: JSON.parse(localStorage.getItem('examenoFeedback') || '[]'),
            formState: JSON.parse(localStorage.getItem('examenoFormState') || '{}'),
            timestamp: new Date().toISOString(),
            type: 'full_system_backup'
        };

        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backup, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", `exameno_full_backup_${new Date().toISOString().split('T')[0]}.json`);
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    };

    const handleRestore = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        if (!window.confirm("WARNING: This will wipe all current data (users, documents, settings) and replace it with the backup. This action cannot be undone. Are you sure?")) {
            event.target.value = '';
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const backup = JSON.parse(e.target?.result as string);

                if (backup.type !== 'full_system_backup') {
                    alert("Invalid backup file. Please select a valid Exameno Full System Backup file.");
                    return;
                }

                if (backup.users) localStorage.setItem('examenoUsers', JSON.stringify(backup.users));
                if (backup.library) localStorage.setItem('examenoLibrary', JSON.stringify(backup.library));
                if (backup.feedback) localStorage.setItem('examenoFeedback', JSON.stringify(backup.feedback));
                if (backup.formState) localStorage.setItem('examenoFormState', JSON.stringify(backup.formState));

                alert("System restored successfully. The page will now reload.");
                window.location.reload();

            } catch (error) {
                console.error("Restore error:", error);
                alert("Failed to restore system. Invalid file format.");
            }
        };
        reader.readAsText(file);
        event.target.value = '';
    };

    return (
        <div className="space-y-6">
            <div className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg p-6">
                <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">Full System Backup & Restore</h3>
                <p className="text-sm text-slate-600 dark:text-slate-400 mb-6">
                    Save a complete copy of all application data (Users, Generated Documents, Settings, Feedback) to a file, or restore from a previous backup.
                    <br/>
                    <span className="text-amber-600 dark:text-amber-400 font-medium">Note: Restoring will overwrite all current data on this device.</span>
                </p>

                <div className="flex flex-col sm:flex-row gap-4">
                    <button
                        onClick={handleBackup}
                        className="flex items-center justify-center px-6 py-3 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="-ml-1 mr-2 h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                        Download Full Backup
                    </button>

                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleRestore}
                        className="hidden"
                        accept=".json"
                    />
                    <button
                        onClick={() => fileInputRef.current?.click()}
                        className="flex items-center justify-center px-6 py-3 border border-red-300 dark:border-red-800 rounded-lg shadow-sm text-sm font-medium text-red-700 dark:text-red-400 bg-white dark:bg-slate-800 hover:bg-red-50 dark:hover:bg-red-900/20 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="-ml-1 mr-2 h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                        </svg>
                        Restore from Backup
                    </button>
                </div>
            </div>
        </div>
    );
};

const AnalyticsDashboard: React.FC<{ currentUser: User, allUsers: User[] }> = ({ currentUser, allUsers }) => {
    const [dateRange, setDateRange] = useState<'5' | '7' | '30' | 'all'>('5');
    const [logSearchTerm, setLogSearchTerm] = useState('');
    const [selectedUserId, setSelectedUserId] = useState<number | 'all'>('all');

    const schoolUserIds = useMemo(() => {
        if (currentUser.role === 'Admin') return null;
        return new Set(allUsers.filter(user => user.schoolName === currentUser.schoolName).map(user => user.id));
    }, [currentUser, allUsers]);

    const availableUsers = useMemo(() => {
        if (currentUser.role === 'Admin') return allUsers;
        return allUsers.filter(u => u.schoolName === currentUser.schoolName);
    }, [allUsers, currentUser]);

    const filteredData = useMemo(() => {
        let data = mockUsageData;
        if (dateRange !== 'all') {
            const days = parseInt(dateRange, 10);
            const cutoff = new Date();
            cutoff.setDate(cutoff.getDate() - days);
            data = data.filter(d => new Date(d.timestamp) >= cutoff);
        }

        if (currentUser.role !== 'Admin') {
             // Filter for school admin
             if (schoolUserIds) {
                 data = data.filter(d => schoolUserIds.has(d.userId));
             }
        }

        if (logSearchTerm) {
             const lower = logSearchTerm.toLowerCase();
             data = data.filter(d => d.grade.toLowerCase().includes(lower) || d.subject.toLowerCase().includes(lower) || d.userName.toLowerCase().includes(lower));
        }

        if (selectedUserId !== 'all') {
            data = data.filter(d => d.userId === selectedUserId);
        }

        return data;
    }, [dateRange, logSearchTerm, currentUser, allUsers, schoolUserIds, selectedUserId]);

