                     <span className="text-sm font-medium text-slate-700 dark:text-slate-300">User:</span>
                     <select value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value === 'all' ? 'all' : parseInt(e.target.value))} className="text-sm rounded-md border-gray-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-white max-w-[150px]">
                         <option value="all">All Users</option>
