import React, { useState } from 'react';
import { GeneratedContent, ExportFormat, ExportHeaderInfo, AssessmentExportType, ContentType } from '../types.ts';
import { formatAsDocx, generateFilename, formatAsExcel, formatAsCsv, formatAsPptx } from '../services/exportService.ts';
import { formatAsPdf } from '../services/pdfService.ts';
import { ICONS } from '../constants.tsx';

const downloadBlob = (blob: Blob, filename: string) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

interface ExportControlsProps {
    content: GeneratedContent;
    layout?: 'row' | 'column' | 'compact';
    headerInfo?: ExportHeaderInfo;
    setHeaderInfo?: React.Dispatch<React.SetStateAction<ExportHeaderInfo>>;
    assessmentExportType?: AssessmentExportType;
    setAssessmentExportType?: React.Dispatch<React.SetStateAction<AssessmentExportType>>;
}

export const ExportControls: React.FC<ExportControlsProps> = ({ 
    content, 
    layout = 'row', 
    headerInfo: controlledHeaderInfo, 
    setHeaderInfo: setControlledHeaderInfo, 
    assessmentExportType: controlledExportType, 
    setAssessmentExportType: setControlledExportType 
}) => {
    const [internalExportType, setInternalExportType] = useState<AssessmentExportType>(AssessmentExportType.QuestionsAndAnswers);
    const [internalHeaderInfo, setInternalHeaderInfo] = useState<ExportHeaderInfo>({
        includeHeader: false,
        schoolName: 'Exameno ECG',
        gradeLevel: content.metadata?.grade || '',
        subject: content.metadata?.subject || '',
        term: content.metadata?.term || '',
        contentType: content.metadata?.contentType || '',
        teacherName: '',
        fontFamily: 'Arial',
        layoutColumns: 'one',
        spacing: 'normal',
        tableStyle: 'lightHorizontalLines',
        pageMargins: 'normal',
        includeAudit: false,
        includeRubric: false,
        includeSummary: false,
        includeBody: true,
    });
    const [isLoading, setIsLoading] = useState<ExportFormat | null>(null);

    const isExportTypeControlled = controlledExportType !== undefined && setControlledExportType !== undefined;
    const assessmentExportType = isExportTypeControlled ? controlledExportType : internalExportType;
    const setAssessmentExportType = isExportTypeControlled ? setControlledExportType : setInternalExportType;

    const isHeaderInfoControlled = controlledHeaderInfo !== undefined && setControlledHeaderInfo !== undefined;
    const headerInfo = isHeaderInfoControlled ? controlledHeaderInfo : internalHeaderInfo;
    const setHeaderInfo = isHeaderInfoControlled ? setControlledHeaderInfo : setInternalHeaderInfo;

    const handleExport = async (format: ExportFormat) => {
        if (!content || isLoading) return;
        setIsLoading(format);

        try {
            switch (format) {
                case ExportFormat.PDF:
                    await formatAsPdf(content, assessmentExportType, headerInfo);
                    break;
                case ExportFormat.Word:
                    const docxBlob = await formatAsDocx(content, assessmentExportType, headerInfo);
                    downloadBlob(docxBlob, generateFilename(content, 'docx', assessmentExportType));
                    break;
                case ExportFormat.Excel:
                    const excelBlob = await formatAsExcel(content, assessmentExportType, headerInfo);
                    downloadBlob(excelBlob, generateFilename(content, 'xlsx', assessmentExportType));
                    break;
                case ExportFormat.CSV:
                    const csvString = await formatAsCsv(content);
                    const csvBlob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
                    downloadBlob(csvBlob, generateFilename(content, 'csv'));
                    break;
                case ExportFormat.PowerPoint:
                    const pptBlob = await formatAsPptx(content, headerInfo);
                    downloadBlob(pptBlob, generateFilename(content, 'pptx')); 
                    break;
            }
        } catch (error) {
            console.error(`Export error (${format}):`, error);
            alert(`Export failed for ${format}. Please try again.`);
        } finally {
            setIsLoading(null);
        }
    };

    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        const isCheckbox = type === 'checkbox';
        const checked = isCheckbox ? (e.target as HTMLInputElement).checked : undefined;
        setHeaderInfo(prev => ({
            ...prev,
            [name]: isCheckbox ? checked : value,
        }));
    };

    const isAssessment = content.questions && content.questions.length > 0;
    const isTabular = !!(content.schemeOfWorkData || content.rowcData);

    const buttons = [
        { format: ExportFormat.Word, icon: ICONS.word, className: "bg-blue-600 hover:bg-blue-500", label: "Word" },
        { format: ExportFormat.PDF, icon: ICONS.pdf, className: "bg-red-600 hover:bg-red-500", label: "PDF" },
        (isAssessment || isTabular) && { format: ExportFormat.Excel, icon: ICONS.excel, className: "bg-emerald-600 hover:bg-emerald-500", label: "Excel" },
        // Fix: Added buttons for CSV and PowerPoint exports to expose existing functionality in the UI.
        (isAssessment || isTabular) && { format: ExportFormat.CSV, icon: ICONS.csv, className: "bg-gray-600 hover:bg-gray-500", label: "CSV" },
        { format: ExportFormat.PowerPoint, icon: ICONS.powerpoint, className: "bg-orange-600 hover:bg-orange-500", label: "PPTX" },
    ].filter(Boolean);

    return (
        <div className="space-y-6">
            <div className={`flex flex-wrap items-center gap-3`}>
                <span className="text-sm font-medium text-gray-500 dark:text-gray-400 mr-2">Export Document:</span>
                {buttons.map((btn) => btn && (
                    <button 
                      key={btn.format} 
                      onClick={() => handleExport(btn.format as ExportFormat)} 
                      disabled={!!isLoading}
                      className={`flex items-center px-4 py-2 text-sm font-medium text-white rounded-lg shadow-sm transition-all hover:-translate-y-0.5 ${btn.className} ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                      {isLoading === btn.format ? '...' : <>{btn.icon} {btn.label}</>}
                    </button>
                ))}
            </div>

            {layout === 'row' && (
                <div className="space-y-6 pt-6 border-t border-gray-200 dark:border-slate-700/60">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {isAssessment && (
                            <fieldset>
                                <legend className="text-sm font-bold text-gray-900 dark:text-white uppercase tracking-wider mb-3">Assessment Options</legend>
                                <div className="space-y-2">
                                    {Object.values(AssessmentExportType).map((type) => (
                                        <div key={type} className="flex items-center">
                                            <input
                                                id={`export-type-${type}`}
                                                name="assessmentExportType"
                                                type="radio"
                                                value={type}
                                                checked={assessmentExportType === type}
                                                onChange={() => setAssessmentExportType(type)}
                                                className="h-4 w-4 text-emerald-600 border-gray-300 focus:ring-emerald-500"
                                            />
                                            <label htmlFor={`export-type-${type}`} className="ml-2 block text-sm text-gray-700 dark:text-gray-300">{type}</label>
                                        </div>
                                    ))}
                                    {content.body && (
                                      <div className="flex items-center pt-2 mt-2 border-t border-gray-200 dark:border-slate-700">
                                          <input 
                                              id="includeBody" 
                                              name="includeBody" 
                                              type="checkbox" 
                                              checked={headerInfo.includeBody !== false} 
                                              onChange={handleHeaderChange} 
                                              className="h-4 w-4 rounded border-gray-300 text-emerald-600 focus:ring-emerald-500" 
                                          />
                                          <label htmlFor="includeBody" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">
                                              Include Content Body
                                          </label>
                                      </div>
                                    )}
                                </div>
                            </fieldset>
                        )}

                        {(content.auditReport || content.summary || content.rubric) && (
                            <fieldset>
                                <legend className="text-sm font-bold text-gray-900 dark:text-white uppercase tracking-wider mb-3">Document Extras</legend>
                                <div className="space-y-2">
                                    {content.summary && (
                                        <div className="flex items-center">
                                            <input id="includeSummary" name="includeSummary" type="checkbox" checked={headerInfo.includeSummary} onChange={handleHeaderChange} className="h-4 w-4 rounded border-gray-300 text-emerald-600 focus:ring-emerald-500" />
                                            <label htmlFor="includeSummary" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">Include Executive Summary</label>
                                        </div>
                                    )}
                                    {content.auditReport && (
                                        <div className="flex items-center">
                                            <input id="includeAudit" name="includeAudit" type="checkbox" checked={headerInfo.includeAudit} onChange={handleHeaderChange} className="h-4 w-4 rounded border-gray-300 text-emerald-600 focus:ring-emerald-500" />
                                            <label htmlFor="includeAudit" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">Include AI Audit Report</label>
                                        </div>
                                    )}
                                    {content.rubric && (
                                        <div className="flex items-center">
                                            <input id="includeRubric" name="includeRubric" type="checkbox" checked={headerInfo.includeRubric} onChange={handleHeaderChange} className="h-4 w-4 rounded border-gray-300 text-emerald-600 focus:ring-emerald-500" />
                                            <label htmlFor="includeRubric" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">Include Grading Rubric</label>
                                        </div>
                                    )}
                                </div>
                            </fieldset>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};
